#include <eosio/eosio.hpp>
#include <eosio/asset.hpp>
#include <eosio/system.hpp>

using namespace eosio;

class [[eosio::contract("vaultcontract")]] vaultcontract : public contract {
public:
    using contract::contract;

    struct [[eosio::table]] vault_config {
        uint64_t id;
        name admin;
        name guardian;
        bool circuit_breaker_active;
        uint32_t cooldown_period;
        uint64_t max_withdrawal;
        uint32_t last_breaker_trip;
        uint64_t total_locked;
        uint8_t governance_threshold;

        uint64_t primary_key() const { return id; }
    };

    struct [[eosio::table]] pending_op {
        uint64_t id;
        name proposer;
        name target_field;
        uint64_t new_value_uint;
        name new_value_name;
        uint32_t proposed_at;
        bool executed;
        uint8_t approvals;

        uint64_t primary_key() const { return id; }
    };

    typedef multi_index<"config"_n, vault_config> config_table;
    typedef multi_index<"pendingops"_n, pending_op> pending_table;

    [[eosio::action]]
    void initialize(name admin, name guardian, uint32_t cooldown, uint64_t max_wd) {
        require_auth(get_self());
        config_table configs(get_self(), get_self().value);
        auto it = configs.find(0);
        check(it == configs.end(), "Already initialized");
        configs.emplace(get_self(), [&](auto& row) {
            row.id = 0;
            row.admin = admin;
            row.guardian = guardian;
            row.circuit_breaker_active = false;
            row.cooldown_period = cooldown;
            row.max_withdrawal = max_wd;
            row.last_breaker_trip = 0;
            row.total_locked = 0;
            row.governance_threshold = 2;
        });
    }

    [[eosio::action]]
    void tripbreaker(name caller) {
        config_table configs(get_self(), get_self().value);
        auto it = configs.find(0);
        check(it != configs.end(), "Not initialized");
        check(caller == it->guardian || caller == it->admin, "Unauthorized");
        require_auth(caller);
        configs.modify(it, same_payer, [&](auto& row) {
            row.circuit_breaker_active = true;
            row.last_breaker_trip = current_time_point().sec_since_epoch();
        });
    }

    [[eosio::action]]
    void propose(name proposer, name target_field, uint64_t new_value_uint, name new_value_name) {
        config_table configs(get_self(), get_self().value);
        auto cfg = configs.find(0);
        check(cfg != configs.end(), "Not initialized");
        check(cfg->circuit_breaker_active == true, "Breaker must be active for governance");
        check(proposer == cfg->admin || proposer == cfg->guardian, "Only admin/guardian can propose");
        require_auth(proposer);

        pending_table pending(get_self(), get_self().value);
        pending.emplace(proposer, [&](auto& row) {
            row.id = pending.available_primary_key();
            row.proposer = proposer;
            row.target_field = target_field;
            row.new_value_uint = new_value_uint;
            row.new_value_name = new_value_name;
            row.proposed_at = current_time_point().sec_since_epoch();
            row.executed = false;
            row.approvals = 1;
        });
    }

    [[eosio::action]]
    void approve(name approver, uint64_t op_id) {
        config_table configs(get_self(), get_self().value);
        auto cfg = configs.find(0);
        check(cfg != configs.end(), "Not initialized");
        check(approver == cfg->admin || approver == cfg->guardian, "Unauthorized");
        require_auth(approver);

        pending_table pending(get_self(), get_self().value);
        auto op = pending.find(op_id);
        check(op != pending.end(), "Op not found");
        check(!op->executed, "Already executed");
        check(op->proposer != approver, "Cannot self-approve");

        pending.modify(op, same_payer, [&](auto& row) {
            row.approvals += 1;
        });
    }

    [[eosio::action]]
    void execute(name caller, uint64_t op_id) {
        config_table configs(get_self(), get_self().value);
        auto cfg = configs.find(0);
        check(cfg != configs.end(), "Not initialized");
        check(caller == cfg->admin || caller == cfg->guardian, "Unauthorized");
        require_auth(caller);

        pending_table pending(get_self(), get_self().value);
        auto op = pending.find(op_id);
        check(op != pending.end(), "Op not found");
        check(!op->executed, "Already executed");
        check(op->approvals >= cfg->governance_threshold, "Insufficient approvals");

        apply_config_change(op->target_field, op->new_value_uint, op->new_value_name);

        pending.modify(op, same_payer, [&](auto& row) {
            row.executed = true;
        });
    }

private:
    void apply_config_change(name field, uint64_t val_uint, name val_name) {
        config_table configs(get_self(), get_self().value);
        auto it = configs.find(0);

        configs.modify(it, same_payer, [&](auto& row) {
            if (field == "admin"_n) {
                row.admin = val_name;
            } else if (field == "guardian"_n) {
                row.guardian = val_name;
            } else if (field == "cooldown"_n) {
                row.cooldown_period = static_cast<uint32_t>(val_uint);
            } else if (field == "maxwd"_n) {
                row.max_withdrawal = val_uint;
            } else if (field == "threshold"_n) {
                row.governance_threshold = static_cast<uint8_t>(val_uint);
            } else if (field == "breaker"_n) {
                row.circuit_breaker_active = (val_uint != 0);
            } else if (field == "locked"_n) {
                row.total_locked = val_uint;
            }
        });
    }
};
